using OperationsRequests.Domain;using OperationsRequests.Services;
namespace OperationsRequests.Tests;
public class ScopeSecurityTests{static readonly ScopeService Scope=new();static TrainingRequest Request()=>new(){Site=new Site{Id=7,TerritoryId=3,Territory=new Territory{Id=3,CountryId=2,Country=new Country{Id=2,Name="ID"}}},SiteId=7,RequestedById="staff"};[Fact]public void Staff_can_only_view_own_request(){var r=Request();Assert.True(Scope.CanView(r,new ApplicationUser{Id="staff",SiteId=7},[Roles.StaffMember]));Assert.False(Scope.CanView(r,new ApplicationUser{Id="other",SiteId=7},[Roles.StaffMember]));}[Fact]public void Territory_scope_blocks_other_territory(){var r=Request();Assert.True(Scope.CanView(r,new ApplicationUser{TerritoryId=3},[Roles.TerritoryManager]));Assert.False(Scope.CanView(r,new ApplicationUser{TerritoryId=4},[Roles.TerritoryManager]));}[Fact]public void Country_scope_blocks_other_country(){var r=Request();Assert.True(Scope.CanView(r,new ApplicationUser{CountryId=2},[Roles.CountryOpsManager]));Assert.False(Scope.CanView(r,new ApplicationUser{CountryId=1},[Roles.CountryOpsManager]));}[Fact]public void Creation_requires_matching_site(){var s=Request().Site;Assert.True(Scope.CanCreateAt(s,new ApplicationUser{SiteId=7},[Roles.StaffMember]));Assert.False(Scope.CanCreateAt(s,new ApplicationUser{SiteId=8},[Roles.StaffMember]));}}
